using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.DependencyInjection.Extensions;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Options;using MongoDB.Driver;using ZosyalMedya.Modules.Notifications.Application.Inbox;using ZosyalMedya.Modules.Notifications.Application.Ports;using ZosyalMedya.Modules.Notifications.Contracts;using ZosyalMedya.Modules.Notifications.Infrastructure.Configuration;using ZosyalMedya.Modules.Notifications.Infrastructure.Delivery;using ZosyalMedya.Modules.Notifications.Infrastructure.Persistence.MongoDb;using ZosyalMedya.Modules.Notifications.Infrastructure.Persistence.PostgreSql;
using ZosyalMedya.BuildingBlocks.Infrastructure.Outbox;
namespace ZosyalMedya.Modules.Notifications.Infrastructure;
public static class DependencyInjection
{public static IServiceCollection AddNotificationsModule(this IServiceCollection s,IConfiguration c){s.AddOptions<NotificationPersistenceOptions>().Bind(c.GetSection(NotificationPersistenceOptions.SectionName)).ValidateDataAnnotations().ValidateOnStart();var o=c.GetSection(NotificationPersistenceOptions.SectionName).Get<NotificationPersistenceOptions>()??throw new InvalidOperationException("Notifications persistence configuration is missing.");if(o.Provider==NotificationPersistenceProvider.PostgreSql){s.AddDbContext<NotificationsDbContext>(x=>x.UseNpgsql(o.PostgreSqlConnectionString));s.AddScoped<INotificationRepository,PostgreSqlNotificationRepository>();}else{s.AddSingleton(_=>new NotificationsMongoDatabase(new MongoClient(o.MongoConnectionString).GetDatabase(o.MongoDatabaseName)));s.AddScoped(sp=>new MongoNotificationRepository(sp.GetRequiredService<NotificationsMongoDatabase>().Database));s.AddScoped<INotificationRepository>(sp=>sp.GetRequiredService<MongoNotificationRepository>());}s.AddScoped<INotificationsModule,NotificationsModule>();s.AddScoped<ListNotificationsHandler>();s.AddScoped<MarkNotificationReadHandler>();s.AddScoped<INotificationChannel,LocalNotificationChannel>();s.AddScoped<IIntegrationEventConsumer,MessageSentNotificationConsumer>();s.AddScoped<IIntegrationEventConsumer,FollowStartedNotificationConsumer>();s.TryAddSingleton<IRealtimeNotificationPublisher,NullRealtimeNotificationPublisher>();s.AddHostedService<NotificationInitializer>();s.AddHostedService<NotificationDeliveryWorker>();return s;}}
internal sealed record NotificationsMongoDatabase(IMongoDatabase Database);internal sealed class NotificationInitializer(IServiceProvider p,IOptions<NotificationPersistenceOptions>o):IHostedService{public async Task StartAsync(CancellationToken t){await using var s=p.CreateAsyncScope();if(o.Value.Provider==NotificationPersistenceProvider.PostgreSql)await s.ServiceProvider.GetRequiredService<NotificationsDbContext>().Database.MigrateAsync(t);else await s.ServiceProvider.GetRequiredService<MongoNotificationRepository>().EnsureIndexesAsync(t);}public Task StopAsync(CancellationToken t)=>Task.CompletedTask;}internal sealed class NullRealtimeNotificationPublisher:IRealtimeNotificationPublisher{public Task PublishAsync(Guid recipientId,object payload,CancellationToken cancellationToken=default)=>Task.CompletedTask;}
